namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Abbreviation { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENG" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and holds a PhD from MIT in Computer Science.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor's research focuses on algorithm optimization. He has published over 40 papers in top-tier conferences.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, Code = "CS 350", Title = "Database Systems", Description = "Design and implementation of relational database systems, SQL, normalization, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Prof. Maria Rodriguez", InstructorBio = "Prof. Rodriguez spent a decade at Oracle before joining academia. She specializes in distributed database systems.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is an award-winning educator who has taught calculus for over 20 years.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov holds a Fields Medal nomination and specializes in applied linear algebra.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 6, Code = "MATH 301", Title = "Differential Equations", Description = "Ordinary differential equations, Laplace transforms, and systems of equations with applications in physics and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is an award-winning educator who has taught calculus for over 20 years.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Fri Lab", InstructorName = "Dr. Richard Feynman Jr.", InstructorBio = "Dr. Feynman Jr. brings physics to life with engaging demonstrations and real-world applications.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Mon/Wed 3:30–4:45 PM + Thu Lab", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma's research in quantum electrodynamics has been published in Nature and Physical Review Letters.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 9, Code = "ENG 101", Title = "English Composition", Description = "Develop writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Prof. David Nguyen", InstructorBio = "Prof. Nguyen is a published novelist and has mentored hundreds of emerging writers.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 10, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Angela Morrison", InstructorBio = "Dr. Morrison is a Pulitzer Prize-nominated critic and scholar of 20th-century American fiction.", DepartmentId = 4, IsFeatured = true },
        new() { Id = 11, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from antiquity through the Renaissance.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright has led archaeological expeditions across the Mediterranean and published three books on ancient civilizations.", DepartmentId = 5, IsFeatured = false },
        new() { Id = 12, Code = "HIST 220", Title = "Modern European History", Description = "Europe from the Enlightenment through the Cold War, emphasizing political and cultural transformations.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Dr. Katarina Johansson", InstructorBio = "Dr. Johansson is a former Fulbright Scholar specializing in 20th-century European political history.", DepartmentId = 5, IsFeatured = false },
    ];

    private readonly List<EnrollmentRequest> _enrollments = [];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

