            <h3>Schedule</h3>
            <p>@course.Schedule</p>

            <h3>Credits</h3>
            <p><span class="badge bg-primary fs-6">@course.Credits credits</span></p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
